#!/usr/bin/env node
/*
 * Builds guides/render.js from guides/md-core.js + guides/render.src.js.
 *
 * The five instrument shims load only https://csi-microscopy.github.io/guides/render.js,
 * so render.js stays a single standalone file: md-core.js (UMD; defines the
 * global CSIMd) followed by the browser part. Edit the two sources, then run
 *   node tools/build-docs/bundle-render.js           # write guides/render.js
 *   node tools/build-docs/bundle-render.js --check   # exit 1 if it is stale (CI)
 */
'use strict';
const fs = require('fs');
const path = require('path');

const GUIDES = path.resolve(__dirname, '../../guides');
const CORE = path.join(GUIDES, 'md-core.js');
const SRC = path.join(GUIDES, 'render.src.js');
const OUT = path.join(GUIDES, 'render.js');

function bundle() {
    const core = fs.readFileSync(CORE, 'utf8');
    const src = fs.readFileSync(SRC, 'utf8');
    const version = (core.match(/const VERSION\s*=\s*'([^']+)'/) || [])[1] || '?';
    return '/* guides/render.js ' + version + ' — GENERATED by tools/build-docs/bundle-render.js from\n'
        + ' * guides/md-core.js and guides/render.src.js. Do not edit this file. */\n\n'
        + '/* ===== guides/md-core.js ===== */\n'
        + core.replace(/\s*$/, '\n')
        + '\n/* ===== guides/render.src.js ===== */\n'
        + src.replace(/\s*$/, '\n');
}

const out = bundle();
if (process.argv.includes('--check')) {
    const cur = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
    if (cur !== out) {
        console.error('guides/render.js is out of date: run  node tools/build-docs/bundle-render.js  and commit the result.');
        process.exit(1);
    }
    console.log('guides/render.js is up to date.');
} else {
    fs.writeFileSync(OUT, out);
    console.log('wrote guides/render.js (' + out.length + ' bytes)');
}
